RULES = [("DROP_TABLE", "high", r"\bDROP\s+TABLE\b", "Drops a table and all of its data."), ("DROP_COLUMN", "high", r"\bDROP\s+COLUMN\b", "Drops a column; old app versions may break."), ("TRUNCATE", "high", r"\bTRUNCATE\b", "Deletes every row in a table."), ("DELETE_NO_WHERE", "high", r"\bDELETE\s+FROM\s+\w+\s*;", "DELETE without WHERE removes all rows."), ("UPDATE_NO_WHERE", "medium", r"\bUPDATE\s+\w+\s+SET\b[^;]*;", "Check this UPDATE has a WHERE clause."), ("SET_NOT_NULL", "medium", r"\bSET\s+NOT\s+NULL\b", "Fails if NULLs exist and scans the whole table."), ("ADD_NOT_NULL_NO_DEFAULT", "medium", r"\bADD\s+COLUMN\s+\w+\s+\w+(\(\d+\))?\s+NOT\s+NULL\s*(;|,)", "NOT NULL column without DEFAULT fails on non-empty tables."), ("ALTER_TYPE", "medium", r"\bALTER\s+COLUMN\s+\w+\s+(SET\s+DATA\s+)?TYPE\b", "Type change can rewrite the table and lock it."), ("CREATE_INDEX_BLOCKING", "low", r"\bCREATE\s+(UNIQUE\s+)?INDEX\s+(?!CONCURRENTLY)", "Use CREATE INDEX CONCURRENTLY to avoid write locks."), ("RENAME", "low", r"\bRENAME\s+(COLUMN|TO)\b", "Renames break running app code."), ("DROP_SCHEMA", "high", r"\bDROP\s+SCHEMA\b", "Drops a schema and everything in it."), ("DROP_DATABASE", "high", r"\bDROP\s+DATABASE\b", "Drops an entire database."), ("DROP_CONSTRAINT", "medium", r"\bDROP\s+CONSTRAINT\b", "Removing a constraint can allow bad data in."), ("ADD_FK_WITHOUT_NOT_VALID", "medium", r'\bADD\s+(?:CONSTRAINT\s+[\w".]+\s+)?FOREIGN\s+KEY\b(?!.*\bNOT\s+VALID\b)', "Use NOT VALID, then VALIDATE CONSTRAINT, to avoid a long lock."), ("VACUUM_FULL", "medium", r"^\s*VACUUM\s+(?:\([^)]*\bFULL\b[^)]*\)|FULL\b)", "VACUUM FULL rewrites the table under an exclusive lock."), ("LOCK_TABLE", "medium", r"^\s*LOCK\b", "Explicit table locks can block traffic.")]
